module protocol::value;

use sui::clock::{Self, Clock};
use math::float::Decimal;


public(package) fun clock_now(clock: &Clock): u64 {
    clock::timestamp_ms(clock) / 1000
}

public fun coin_value(price: Decimal, amount: Decimal, decimals: u8): Decimal {
    let divisor = math::float::from(10u64.pow(decimals));
    price.mul(amount).div(divisor)
}

#[test_only]
public(package) fun usd_value_deprecated(price: Decimal, amount: u64, decimals: u8): Decimal {
    let decimal_amount = math::float::from_quotient(amount, 10u64.pow(decimals));
    math::float::mul(price, decimal_amount)
}

#[test]
public(package) fun test_usd_value() {
    let price = math::float::from_quotient(2627, 1_000_000); // $0.002627
    let decimals = 5;
    let amount = math::float::from(20_000_350_000 * 10u64.pow(decimals));
    let val = coin_value(price, amount, decimals);
    assert!(val.eq(math::float::from_quotient(5254091945, 100)));
}

#[test]
public(package) fun test_usd_value_result_should_equal() {
    let price = math::float::from_quotient(2627, 1_000_000); // $0.002627
    let decimals = 5;
    let amount = 200_003_500 * 10u64.pow(decimals);
    let val = coin_value(price, math::float::from(amount), decimals);
    let val_old = usd_value_deprecated(price, amount, decimals);
    assert!(val == val_old, 0);
}

