   613→public(package) fun handle_collateral_auto_deleverage<MarketType, DebtType, CollateralType>(
   614→    self: &mut Market<MarketType>,
   615→    obligation_id: ID,
   616→    available_repay_coin: Coin<DebtType>,
   617→    coin_decimals_registry: &CoinDecimalsRegistry,
   618→    x_oracle: &XOracle,
   619→    clock: &Clock,
   620→    now: u64,
   621→    ctx: &mut TxContext,
   622→): (Coin<CollateralType>, Coin<DebtType>, u64) {
   623→    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;
   624→
   625→    let collateral = type_name::with_defining_ids<CollateralType>();
   626→
   627→    // load the time locked adl params
   628→    let adl_registry = self.adl_registry<MarketType>();
   629→    let timelock = *adl_registry.get_collateral_deleverage(collateral);
   630→
   631→    // refresh obligation
   632→    let obligation = self.obligations.borrow_mut(obligation_id);
   633→    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());
   634→
   635→    // obtain the emode group
   636→    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());
   637→
   638→    // make sure the Collateral Type is indeed a collateral, otherwise revert
   639→    let collateral_setting = emode_group.borrow_emode(collateral).collateral();
   640→    // cannot liquidate asset that is not collateral
   641→    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());
   642→    
   643→    let max_liquidation_incentive = collateral_setting.liquidation_incentive();
   644→
   645→    // force interest update for the collateral asset
   646→    let asset = self.assets.load_mut_by_type(collateral);
   647→    accrue_interest<MarketType>(collateral, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);
   648→
   649→    let total_deposit = self.reserves.load_by_type(collateral).cash_plus_borrows_minus_reserves().floor();
   650→    let collateral_params = timelock.inner();
   651→    collateral_params.ensure_limit_breached(total_deposit);
   652→    let activation_time = timelock.get_secs_since_activation(clock);
   653→
   654→    let liquidation_params = LiquidationParams {
   655→        liquidation_ltv_threshold_override: std::option::some(collateral_params.liquidation_ltv(activation_time)),
   656→        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
   657→        liquidation_incentive: collateral_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
   658→        liquidation_revenue_factor: float::zero(),
   659→        close_factor: collateral_params.close_factor(),
   660→        close_factor_bypass_min_value,
   661→    };
   662→
   663→    liquidation_inner<MarketType, DebtType, CollateralType>(
   664→        &mut self.id,
   665→        &self.assets,
   666→        emode_group,
   667→        &mut self.reserves,
   668→        obligation,
   669→        &liquidation_params,
   670→        available_repay_coin,
   671→        coin_decimals_registry,
   672→        x_oracle,
   673→        clock,
   674→        now,
   675→        ctx,
   676→    )
   677→}
