   795→public(package) fun borrow_flash_loan<MarketType, CoinType>(
   796→    self: &mut Market<MarketType>,
   797→    emode_group: u8,
   798→    amount: u64,
   799→    ctx: &mut TxContext,
   800→): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
   801→    let asset = self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   802→
   803→    assert!(!asset.flash_loan_paused(), error::flash_loan_paused_for_asset());
   804→    assert!(!asset.flash_loan_ongoing(), error::flash_loan_ongoing());
   805→
   806→    asset.flash_loan_triggered<MarketType>();
   807→
   808→    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   809→
   810→    let emode = self.emode_group_registry.borrow_emode_group(emode_group).borrow_emode(type_name::with_defining_ids<CoinType>());
   811→    let flash_loan_fee_rate = emode.flash_loan().fee_rate();
   812→
   813→    let fee = flash_loan_fee_rate.int_mul(amount);
   814→    assert!(fee != 0, error::reserve_flash_loan_fee_too_small());
   815→
   816→    let (balance, inner) = reserve.borrow_flash_loan(amount);
   817→    (balance.into_coin(ctx), FlashLoan<MarketType, CoinType> { inner, fee })
   818→}
   819→
   820→public(package) fun repay_flash_loan<MarketType, CoinType>(
   821→    self: &mut Market<MarketType>,
   822→
   823→    mut coin: Coin<CoinType>,
   824→    loan: FlashLoan<MarketType, CoinType>,
   825→
   826→    referral: &mut protocol::referral::Referral,
   827→    mut maybe_referral_code: Option<String>,
   828→
   829→    ctx: &mut TxContext
   830→) {
   831→    let asset = self.assets.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   832→
   833→    assert!(asset.flash_loan_ongoing(), error::flash_loan_not_ongoing());
   834→    asset.flash_loan_finished<MarketType>();
   835→
   836→    let FlashLoan { inner, fee } = loan;
   837→    assert!(coin.value() == inner.amount() + fee, error::reserve_flash_loan_not_paid_enough());
   838→
   839→    let mut fee_coin = coin.split(fee, ctx);
   840→
   841→    if (maybe_referral_code.is_some()) {
   842→        let referral_code = maybe_referral_code.extract();
   843→        fee_coin = referral.track_flash_loan_usage(
   844→            fee_coin,
   845→            referral_code,
   846→            ctx.sender(),
   847→            ctx,
   848→        );
   849→        
   850→        // no free ride after rebate
   851→        assert!(fee_coin.value() != 0, error::reserve_flash_loan_fee_too_small());
   852→    };
   853→
   854→    let reserve = self.reserves.load_mut_by_type(type_name::with_defining_ids<CoinType>());
   855→    reserve.repay_flash_loan(inner, coin, fee_coin);
   856→}
   857→
   858→fun refresh_obligation_assets_interest<MarketType>(
   859→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   860→    emode_group: &EModeGroup,
   861→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   862→    obligation: &mut Obligation<MarketType>,
   863→    now: u64,
   864→) {
   865→    refresh_obligation_borrow_interest<MarketType>(assets, reserves, obligation, now);
   866→
   867→    // collateral
   868→    let asset_types = obligation.deposit_types();
   869→
   870→    let (mut i, n) = (0, asset_types.length());
   871→
   872→    while (i < n) {
   873→        let name = asset_types[i];
   874→
   875→        let asset = assets.load_by_type(name);
   876→        let collateral_settings = emode_group.borrow_emode(name).collateral();
   877→
   878→        // update index first, since it's not used after this point
   879→        i = i + 1;
   880→
   881→        // cannot be collateral, ignore
   882→        if (!collateral_settings.can_be_collateral()) { continue };
   883→
   884→        accrue_interest<MarketType>(name, reserves, asset.asset_config(), asset.interest_model(), now);
   885→    };
   886→}
   887→
   888→fun refresh_obligation_borrow_interest_with_new_borrow<MarketType>(
   889→    maybe_new_borrow_coin_type: TypeName,
   890→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   891→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   892→    obligation: &mut Obligation<MarketType>,
   893→    now: u64,
   894→) {
   895→
   896→    refresh_obligation_borrow_interest<MarketType>(assets, reserves, obligation, now);
   897→
   898→    if (obligation.has_debt(maybe_new_borrow_coin_type)) { return };
   899→
   900→    let asset = assets.load_by_type(maybe_new_borrow_coin_type);
   901→    accrue_interest(maybe_new_borrow_coin_type, reserves, asset.asset_config(), asset.interest_model(), now);
   902→}
   903→
   904→fun refresh_obligation_borrow_interest<MarketType>(
   905→    assets: &GenericCoinTypeStorage<Asset<MarketType>>,
   906→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
   907→    obligation: &mut Obligation<MarketType>,
   908→    now: u64,
   909→) {
   910→    let asset_types = obligation.debt_types();
   911→
   912→    let (mut i, n) = (0, asset_types.length());
   913→
   914→    while (i < n) {
   915→        let name = asset_types[i];
   916→
   917→        let asset = assets.load_by_type(name);
   918→
   919→        let reserve = accrue_interest<MarketType>(name, reserves, asset.asset_config(), asset.interest_model(), now);
   920→        obligation.accrue_interest(name, reserve.borrow_index().value());
   921→
   922→        i = i + 1;
   923→    };
   924→}
   925→
   926→/// Make sure the caller has refresh all obligation debt and collateral interest before calling this method
   927→fun ensure_liquidate_borrow_allowed<MarketType, DebtType>(
   928→    liquidation_params: &LiquidationParams,
   929→
   930→    obligation: &Obligation<MarketType>,
   931→
   932→    emode_group: &EModeGroup,
   933→
   934→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
   935→
   936→    coin_decimals_registry: &CoinDecimalsRegistry,
   937→    liquidator_repay_amount: u64,
   938→
   939→    x_oracle: &XOracle,
   940→
   941→    clock: &Clock,
   942→) {
   943→    // make sure that their obligation still healthy, so users aren't borrowing over their collateral
   944→    let (weighted_debts_value, debts_total_value) = debts_value_usd_for_liquidation(
   945→        emode_group,
   946→        reserves,
   947→        obligation,
   948→        coin_decimals_registry,
   949→        x_oracle,
   950→        clock,
   951→    );
   952→
   953→    let (collateral_weighted_value, collateral_total_value) = collaterals_usd_for_liquidation(
   954→        emode_group,
   955→        reserves,
   956→        obligation,
   957→        coin_decimals_registry,
   958→        x_oracle,
   959→        clock,
   960→    );
   961→
   962→    // triggering condition: 
   963→    // user_ltv > liquidation_ltv
   964→    if (liquidation_params.liquidation_ltv_threshold_override.is_some()) {
   965→        let liquidation_ltv = *liquidation_params.liquidation_ltv_threshold_override.borrow();
   966→        let user_ltv = weighted_debts_value.div(collateral_total_value);
   967→        assert!(
   968→            user_ltv.gt(liquidation_ltv),
   969→            error::liquidation_obligation_still_safe(),
   970→        );
   971→    } else {
   972→        // user_ltv = weighted_debts_value / collateral_total_value
   973→        // liquidation_ltv = collateral_weighted_value / collateral_total_value
   974→        // user_ltv > liquidation_ltv
   975→        //    weighted_debts_value / collateral_total_value > collateral_weighted_value / collateral_total_value
   976→        //    weighted_debts_value / collateral_weighted_value > liquidation_ltv_threshold
   977→        //    weighted_debts_value > collateral_weighted_value * liquidation_ltv_threshold
   978→        assert!(
   979→            weighted_debts_value.gt(collateral_weighted_value),
   980→            error::liquidation_obligation_still_safe(),
   981→        );
   982→    };
   983→
   984→    // Note that the close factor is enforce ONLY when the obligation is not close to bad debt
   985→    let bad_debt_close_factor_bypass_threshold = float::from_quotient(101, 100);
   986→    let bad_debt_threshold = bad_debt_close_factor_bypass_threshold.mul(debts_total_value);
   987→
   988→    if (collateral_total_value.le(bad_debt_threshold)) {
   989→        // This means the obligation is close to bad debt, allow close whatever is passed
   990→        // close factor effectively equals to 1.
   991→        return
   992→    };
   993→
   994→    let target_debt_type = type_name::with_defining_ids<DebtType>();
   995→
   996→    let debt_balance = obligation.debt(target_debt_type).unsafe_debt_amount();
   997→    let debt_value = coin_value(
   998→        get_price(x_oracle, target_debt_type, emode_group.get_oracle_base_token(), clock),
   999→        debt_balance,
  1000→        coin_decimals_registry.decimals(target_debt_type)
  1001→    )
  1002→        // this is tricky, because it is using ceiling, this mean if the debt value is say 9.8, the ceiling is 10
  1003→        .ceil();
  1004→
  1005→    // below min usd for close factor enforcement
  1006→    if (debt_value <= liquidation_params.close_factor_bypass_min_value) { return };
  1007→
  1008→    let max_debt_amount = debt_balance.mul(liquidation_params.close_factor);
  1009→    assert!(
  1010→        math::float::from(liquidator_repay_amount).le(max_debt_amount),
  1011→        error::liquidation_close_factor_exceeded(),
  1012→    );
  1013→}
  1014→
  1015→fun accrue_interest<MarketType>(
  1016→    coin_type: TypeName,
  1017→    reserves: &mut GenericCoinTypeStorage<Reserve<MarketType>>,
  1018→    asset: &AssetConfig,
  1019→    interest_model: &InterestModel,
  1020→    now: u64,
  1021→): &mut Reserve<MarketType> {
  1022→    let reserve = reserves.load_mut_by_type(coin_type);
  1023→
  1024→    let interest_rate = interest_model.calc_interest(reserve.util_rate());
  1025→    reserve.accrue_interest(asset.repay_fee_rate(), interest_rate, now);
  1026→
  1027→    reserve
  1028→}
  1029→
  1030→// calculate the actual repay amount, actual liquidate amount, actual market amount
  1031→fun liquidate_calculate_seize_ctokens<DebtType, CollateralType>(
  1032→    exchange_rate: Decimal,
  1033→    liquidation_incentive: Decimal,
  1034→    actual_repay_amount: u64,
  1035→
  1036→    oracle_base_token: x_oracle::x_oracle::BaseToken,
  1037→    x_oracle: &XOracle,
  1038→
  1039→    coin_registry: &CoinDecimalsRegistry,
  1040→    clock: &Clock,
  1041→): u64 {
  1042→    let debt_type = type_name::with_defining_ids<DebtType>();
  1043→    let collateral_type = type_name::with_defining_ids<CollateralType>();
  1044→
  1045→    let price_borrowed = get_spot_price(x_oracle, debt_type, oracle_base_token, clock);
  1046→    let price_collateral = get_spot_price(x_oracle, collateral_type, oracle_base_token, clock);
  1047→
  1048→    let actual_repay_amount = float::from(actual_repay_amount);
  1049→
  1050→    let debt_decimals = math::u64::pow10_u64(coin_registry.decimals(debt_type));
  1051→    let collateral_decimals = math::u64::pow10_u64(coin_registry.decimals(collateral_type));
  1052→
  1053→    /*
  1054→     * Get the exchange rate and calculate the number of collateral tokens to seize:
  1055→     *  seizeAmount = (actualRepayAmount + actualRepayAmount * liquidationIncentive) * priceBorrowed / priceCollateral
  1056→     *  seizeTokens = seizeAmount / exchangeRate
  1057→     */
  1058→    let incentivised_borrow = actual_repay_amount.add(actual_repay_amount.mul(
  1059→        liquidation_incentive,
  1060→    ));
  1061→    // ignoreing decimal calculation as they will be cancelled out
  1062→    let incentivised_borrow_usd = incentivised_borrow.mul(price_borrowed).div_u64(debt_decimals);
  1063→    let seize_collaterals = incentivised_borrow_usd.div(price_collateral).mul_u64(collateral_decimals);
  1064→
  1065→    let seize_ctokens = seize_collaterals.div(exchange_rate);
  1066→
  1067→    assert!(
  1068→        seize_ctokens.lt(float::from(std::u64::max_value!())),
  1069→        error::invariant_seize_tokens_crazy_big(),
  1070→    );
  1071→
  1072→    // only take the tecnnically possible amount
  1073→    seize_ctokens.floor()
  1074→}
  1075→
  1076→public struct LiquidationParams has drop {
  1077→    liquidation_ltv_threshold_override: Option<Decimal>,
  1078→    liquidation_incentive: Decimal,
  1079→    liquidation_revenue_factor: Decimal,
  1080→    close_factor: Decimal,
  1081→    // close factor will not be enforce if the debt being liquidated has usd value less or equal to this value
  1082→    close_factor_bypass_min_value: u64,
  1083→}
  1084→
  1085→// sum of every collateral usd value for borrow, returns both the total collateral usd value and the collateral factor weighted usd value (price x amount x collateralFactor)
  1086→fun collaterals_usd_for_liquidation<MarketType>(
  1087→    emode_group: &EModeGroup,
  1088→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1089→
  1090→    obligation: &Obligation<MarketType>,
  1091→
  1092→    coin_decimals_registry: &CoinDecimalsRegistry,
  1093→    x_oracle: &XOracle,
  1094→    clock: &Clock,
  1095→): (Decimal, Decimal) {
  1096→    let mut total_weighted_usd = float::zero();
  1097→    let mut total_collateral_usd = float::zero();
  1098→
  1099→    let mut deposit_types = obligation.deposit_types();
  1100→    let oracle_base_token = emode_group.get_oracle_base_token();
  1101→
  1102→    while (!deposit_types.is_empty()) {
  1103→        let deposit_type = deposit_types.pop_back();
  1104→
  1105→        let collateral_config = emode_group.borrow_emode(deposit_type).collateral();
  1106→        // cannot be collateral, ignore
  1107→        if (!collateral_config.can_be_collateral()) { continue };
  1108→        
  1109→        let weight = collateral_config.liquidation_factor();
  1110→
  1111→        let ctoken_amount = obligation.ctoken_amount_by_coin<MarketType>(deposit_type);
  1112→        let reserve = reserves.load_by_type<Reserve<MarketType>>(deposit_type);
  1113→        let collateral_amount = reserve.exchange_rate().mul(float::from(ctoken_amount));
  1114→
  1115→        let coin_price = get_price(x_oracle, deposit_type, oracle_base_token, clock);
  1116→        let decimals = coin_decimals_registry.decimals(deposit_type);
  1117→        
  1118→        let collateral_value_usd = coin_value(coin_price, collateral_amount, decimals);
  1119→        let collateral_weighted_usd = collateral_value_usd.mul(weight);
  1120→
  1121→        total_collateral_usd = total_collateral_usd.add(collateral_value_usd);
  1122→        total_weighted_usd = total_weighted_usd.add(collateral_weighted_usd);
  1123→    };
  1124→
  1125→    (total_weighted_usd, total_collateral_usd)
  1126→}
  1127→
  1128→/// Calculates the debts in usd against latest oracle ema price, without including the borrow weights
  1129→fun debts_value_usd_for_liquidation<MarketType>(
  1130→    emode_group: &EModeGroup,
  1131→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1132→
  1133→    obligation: &Obligation<MarketType>,
  1134→
  1135→    coin_decimals_registry: &CoinDecimalsRegistry,
  1136→
  1137→    x_oracle: &XOracle,
  1138→    clock: &Clock,
  1139→): (Decimal, Decimal) {
  1140→    let mut total_weighted_value_usd = float::zero();
  1141→    let mut total_value_usd = float::zero();
  1142→
  1143→    let debt_types = obligation.debt_types();
  1144→    let (mut i, n) = (0, debt_types.length());
  1145→
  1146→    let oracle_base_token = emode_group.get_oracle_base_token();
  1147→
  1148→    while (i < n) {
  1149→        let debt_type = *debt_types.borrow(i);
  1150→
  1151→        let reserve = reserves.load_by_type(debt_type);
  1152→
  1153→        let debt_amount = obligation.debt(debt_type).debt(reserve.borrow_index().value());
  1154→        let decimals = coin_decimals_registry.decimals(debt_type);
  1155→        let coin_price = get_price(x_oracle, debt_type, oracle_base_token, clock);
  1156→
  1157→        let coin_value_usd = coin_value(coin_price, debt_amount, decimals);
  1158→        total_value_usd = total_value_usd.add(coin_value_usd);
  1159→
  1160→        let borrow_weight = emode_group.borrow_emode(debt_type).borrow().borrow_weight();
  1161→        total_weighted_value_usd = total_weighted_value_usd.add(coin_value_usd.mul(borrow_weight));
  1162→
  1163→        i = i + 1;
  1164→    };
  1165→
  1166→    (total_weighted_value_usd, total_value_usd)
  1167→}
  1168→
  1169→/// Calculates the debts in usd against latest oracle price. Returns the total usd value then the borrow_weight weighted usd value
  1170→fun debts_value_usd_non_liquidation<MarketType>(
  1171→    emode_group: &EModeGroup,
  1172→    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
  1173→    ema_spot_tolerance: &GenericCoinTypeStorage<Decimal>,
  1174→
  1175→    obligation: &Obligation<MarketType>,
  1176→
  1177→    coin_decimals_registry: &CoinDecimalsRegistry,
  1178→
  1179→    x_oracle: &XOracle,
  1180→    clock: &Clock,
  1181→): Decimal {
  1182→    let mut total_weighted_value_usd = float::zero();
  1183→
  1184→    let debt_types = obligation.debt_types();
  1185→    let (mut i, n) = (0, debt_types.length());
  1186→
  1187→    let oracle_base_token = emode_group.get_oracle_base_token();
  1188→
  1189→    while (i < n) {
  1190→        let debt_type = *debt_types.borrow(i);
